@@ -260,9 +268,13 @@ function updatePullRequestBody(scm, prNumber, ticketKey, testStatus, bodyContent
     if (!bodyContent) return false;

     try {
-        const body = '## ' + ticketKey + ' Result: ' + testStatus.toUpperCase() + '\n\n' +
