+        const refreshed = '## ' + ticketKey + ' Result: ' + testStatus.toUpperCase() + '\n\n' +
             '**Latest rework result:** `' + testStatus.toUpperCase() + '`\n\n' +
             '---\n\n' + bodyContent;
+        const body = prHelper.ensureClosesLine(refreshed, ticketKey);
         if (scm.updatePrBody) {
