// accepts Fixes/Part-of, but the pack still emits canonical Closes — a
// non-canonical keyword never substitutes for it.
var GITHUB_ISSUE_KEY = /^gh-\d+$/i;

/**
 * Extracts the trailing issue number from a ticket key (gh-737 → '737',
 * PROJ-123 → '123'). Returns null when the key carries no digits.
 */
function extractIssueNumber(ticketKey) {
    var m = /(\d+)\s*$/.exec(String(ticketKey || '').trim());
    return m ? m[1] : null;
}

/**
 * Guarantees the body contains the canonical 'Closes #N' line for the ticket.
 * Idempotent: a body that already closes the same issue is left untouched;
 * any other keyword (Fixes/Part-of) still gets the canonical line added.
 * Keys that are not GitHub router keys (gh-N) leave the body unchanged.
 */
function ensureClosesLine(body, ticketKey) {
    // Only GitHub router keys (gh-N) map to a closeable GitHub issue; tracker keys
    // such as PROJ-123 would produce a bogus 'Closes #123' link.
    if (!GITHUB_ISSUE_KEY.test(String(ticketKey || '').trim())) return body;
    var num = extractIssueNumber(ticketKey);
    if (!num) return body;

    var text = body === null || body === undefined ? '' : String(body);
    if (new RegExp('\\bCloses\\s+#?' + num + '\\b', 'i').test(text)) return text;

    return 'Closes #' + num + '\n' + text;
}

// gh-960: the PR body (including the canonical 'Closes #N' line) must be final
// BEFORE the PR enters the merge queue. Live 2026-10-17: PR #956 merged with
// 'Closes #952' added to the body at the merge moment (finalize-step rewrite
// after validation armed) — GitHub evaluates closing keywords on creation
// and body edits, never post-merge, so #952 stayed OPEN. From the moment the
// validate→merge pipeline arms (ai_validating on the PR) or the PR is
// merged/closed, a body rewrite is too late and must be skipped.
var MERGE_QUEUE_BODY_LABELS = ['ai_validating'];

/**
 * Whether the PR body must be treated as final — the PR entered the merge
 * queue (validation armed) or is already merged/closed. Accepts both GitHub
 * REST label shapes ({name: …} objects) and plain-string label arrays.
 */
function isPrBodyFrozen(pr) {
    if (!pr || typeof pr !== 'object') return false;
    if (pr.merged === true) return true;
    var state = String(pr.state || '').toLowerCase();
    if (state === 'closed' || state === 'merged') return true;
    var labels = pr.labels || [];
    for (var i = 0; i < labels.length; i++) {
        var name = labels[i] && labels[i].name !== undefined ? labels[i].name : labels[i];
        if (MERGE_QUEUE_BODY_LABELS.indexOf(String(name)) !== -1) return true;
    }
    return false;
}

// GitHub limits PR bodies to 65536 characters. Keep a safety margin so
// gh pr create does not fail on oversized bodies generated by agents.

        customParams: customParams,
        section: 'qualityGates'
    });
    if (!gateResult.success) {
        throw new Error('Quality gate failed before test rework publish: ' + gateResult.failedGate + '\n' + gateResult.error);
    }
    var policyResult = feedbackLoop.runPolicyGates({
        ticketKey: ticketKey,
        customParams: customParams,
        section: 'policyGates'
    });
    if (!policyResult.success) {
        throw new Error('Policy gate failed before test rework publish: ' + policyResult.failedGate + '\n' + policyResult.error);
    }
}

/** Release the rework WIP label (and the custom SM label when configured). */
function releaseReworkLock(ticketKey, wipLabel, removeLabel) {
    try { getTracker().removeLabel(ticketKey, wipLabel); } catch (e) {}
    if (removeLabel) {
        try {
            getTracker().removeLabel(ticketKey, removeLabel);
            console.log('✅ Removed SM label:', removeLabel);
        } catch (e) {}
    }
}

/** PR body refresh + rework summary comment; failures are non-fatal warns. */
function postReworkBodyAndComment(scm, pr, ticketKey, testStatus, passed, prBodyContent) {
    try {
        // gh-960: once the PR entered the merge queue (validation armed) or is
        // merged/closed, the body is final — a rewrite there lands too late for
        // GitHub to parse closing keywords (live #956/#952). The summary comment
        // is unaffected and still posts.
        if (prHelper.isPrBodyFrozen(pr)) {
            console.warn('PR #' + (pr && pr.number) + ' body is final (merge queue entered or merged) — skipping body rewrite (gh-960)');
        } else {
            updatePullRequestBody(scm, pr.number, ticketKey, testStatus, prBodyContent);
        }
        scm.addComment(pr.number, buildPRReworkComment(ticketKey, testStatus, passed, prBodyContent));
        console.log('✅ Posted rework summary to PR');
    } catch (e) {
        console.warn('Failed to post PR comment:', e);
    }
}

/** The review-thread identifier for a reply item (threadId, else discussionId). */
function replyThreadIdOf(item) {
    return item.threadId || item.discussionId;
}

/**
 * One outputs/review_replies.json entry: post the explicit thread reply
 * and/or resolve the thread. Mutates the tally; call order is list order.
 */
function handleReplyItem(scm, pullRequestId, item, tally) {
    const thread = {
        rootCommentId: item.inReplyToId,
        threadId: replyThreadIdOf(item)
    };
    const replyText = item.reply ? String(item.reply).trim() : '';

    // Only post a reply when the agent explicitly wrote one AND we have the
    // identifiers needed to reply inside the existing review thread. Without
    // rootCommentId GitHub's SCM fallback creates a generic issue comment,
    // which is what produces the huge "✅ Addressed." comment floods.
    if (replyText && item.inReplyToId) {
        try {
            scm.replyToThread(pullRequestId, thread, replyText);
