    var goldenDesc = "";
    for (var k = 0; k < descChanges.length; k++) {
        var candidate = descChanges[k].toString;
        if (candidate.length > goldenDesc.length) {
            goldenDesc = candidate;
        }
        candidate = descChanges[k].fromString;
        if (candidate.length > goldenDesc.length) {
            goldenDesc = candidate;
        }
    }

